function hash(value){return crypto.createHash('sha256').update(value).digest('hex');}
async function fileHash(filePath){return hash(await fsp.readFile(filePath));}
async function writeJson(filePath,value){await fsp.mkdir(path.dirname(filePath),{recursive:true});await fsp.writeFile(filePath,JSON.stringify(value,null,2)+'\n','utf8');}
async function tree(root,relative=''){const rows=[];if(!fs.existsSync(root))return rows;for(const entry of (await fsp.readdir(path.join(root,relative),{withFileTypes:true})).sort((a,b)=>a.name.localeCompare(b.name))){const child=relative?path.posix.join(relative,entry.name):entry.name;const target=path.join(root,...child.split('/'));const stats=await fsp.lstat(target);if(stats.isSymbolicLink())rows.push(child+'|symlink|'+await fsp.readlink(target));else if(stats.isDirectory())rows.push(...await tree(root,child));else{const bytes=await fsp.readFile(target);rows.push(child+'|'+bytes.length+'|'+hash(bytes));}}return rows;}
async function treeHash(root){return hash(Buffer.from((await tree(root)).sort().join('\n')+'\n','utf8'));}
async function copySkillSource(target){await fsp.mkdir(target,{recursive:true});for(const skill of SKILLS)await fsp.cp(path.join('C:\\Users\\lsb\\.codex\\skills',skill),path.join(target,skill),{recursive:true});}
async function installBundle(options){return installBundleRaw({...options,testMode:true,expectedInstallRoot:path.resolve(options.installRoot)});}
async function verify(options){return verifyRaw({...options,testMode:true,expectedSkillRoot:path.resolve(options.skillRoot)});}

